(1, 'Gói 100K', 100000.00, '																																																																																																																																																																<div><br></div><table class=\"table table-bordered\"><tbody><tr><td style=\"text-align: left;\"><span style=\"text-align: center;\">Kim Cương</span><br></td><td style=\"text-align: left;\"><span style=\"text-align: center;\">3000</span><br></td></tr><tr><td style=\"text-align: left;\"><span style=\"text-align: center;\">Vàng</span><br></td><td style=\"text-align: left;\"><span style=\"text-align: center;\">3000000</span><br></td></tr><tr><td style=\"text-align: left;\"><span style=\"text-align: center;\">Gói Nguyên Liệu Đột Phá</span><br></td><td style=\"text-align: left;\">20</td></tr><tr><td style=\"text-align: left;\"><span style=\"text-align: center;\">Phiếu Rút Thẻ Kim Cương</span><br></td><td style=\"text-align: left;\"><span style=\"text-align: center;\">30</span><br></td></tr><tr><td style=\"text-align: left;\"><span style=\"text-align: center;\">Mảnh Vạn Năng Đỏ</span><br></td><td style=\"text-align: left;\"><span style=\"text-align: center;\">15</span><br></td></tr><tr><td style=\"text-align: left;\"><span style=\"text-align: center;\">Rương Vật Phẩm Thức Tỉnh Trang Sức</span><br></td><td style=\"text-align: left;\"><span style=\"text-align: center;\">1</span><br></td></tr><tr><td style=\"text-align: left;\"><span style=\"text-align: center;\">Mảnh Vạn Năng Vàng</span><br></td><td style=\"text-align: left;\"><span style=\"text-align: center;\">30</span><br></td></tr></tbody></table><div><br></div>																																																																																																																																																', '1'),
