-- --------------------------------------------------------

--
-- Cấu trúc bảng cho bảng `history`
--

CREATE TABLE `history` (
  `id` int NOT NULL,
  `cAccName` varchar(255) CHARACTER SET latin1 COLLATE latin1_swedish_ci DEFAULT NULL,
  `Content` text CHARACTER SET utf8 COLLATE utf8_bin,
  `timeDate` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  `type` varchar(255) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=COMPACT;

-- --------------------------------------------------------

--
-- Cấu trúc bảng cho bảng `invoice`
--

CREATE TABLE `invoice` (
  `id` int NOT NULL,
  `invoice_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Mã hóa đơn unique (VD: INV1706234567)',
  `username` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'User tạo hóa đơn',
  `amount` int NOT NULL COMMENT 'Số tiền cần thanh toán (VND)',
  `xu_receive` int NOT NULL COMMENT 'Số xu sẽ nhận được',
  `status` tinyint DEFAULT '0' COMMENT '0=Đang xử lý, 1=Hoàn tất, 2=Đã hủy',
  `bank_transaction_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Mã giao dịch ngân hàng',
  `note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Ghi chú',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'Thời gian tạo',
  `expired_at` timestamp NULL DEFAULT NULL COMMENT 'Thời gian hết hạn',
  `paid_at` timestamp NULL DEFAULT NULL COMMENT 'Thời gian thanh toán',
  `cancelled_at` timestamp NULL DEFAULT NULL COMMENT 'Thời gian hủy'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Cấu trúc bảng cho bảng `log_event_tichluy`
--

CREATE TABLE `log_event_tichluy` (
  `id` int NOT NULL,
  `username` varchar(255) DEFAULT NULL,
  `pack_id` int DEFAULT NULL,
  `timeDate` timestamp NULL DEFAULT NULL,
  `code` varchar(255) DEFAULT NULL,
  `name` varchar(255) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 ROW_FORMAT=DYNAMIC;

-- --------------------------------------------------------

--
-- Cấu trúc bảng cho bảng `log_rechagre`
--

CREATE TABLE `log_rechagre` (
  `id` int NOT NULL,
  `rechargeID` int DEFAULT NULL,
  `rechargeName` varchar(255) DEFAULT NULL,
  `rechargePrice` int DEFAULT NULL,
  `timeDate` timestamp NULL DEFAULT NULL,
  `username` varchar(255) DEFAULT NULL,
  `account_id` varchar(255) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 ROW_FORMAT=DYNAMIC;

-- --------------------------------------------------------

--
-- Cấu trúc bảng cho bảng `rechagre`
--

CREATE TABLE `rechagre` (
  `id` int NOT NULL,
  `rechargeID` int DEFAULT NULL,
  `rechargeName` varchar(255) DEFAULT NULL,
  `rechargrePrice` int DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 ROW_FORMAT=DYNAMIC;

